<?php
require_once dirname(__DIR__).'/app/bootstrap.php';$token=trim((string)($_GET['token']??''));$s=db()->prepare("SELECT c.*,u.name creator FROM saved_collections c JOIN users u ON u.id=c.user_id WHERE c.share_token=:t AND c.visibility IN ('public','unlisted') LIMIT 1");$s->execute([':t'=>$token]);$collection=$s->fetch();if(!$collection){http_response_code(404);send_not_found();}$s=db()->prepare("SELECT l.* FROM saved_collection_items i JOIN listings l ON l.id=i.listing_id WHERE i.collection_id=:c AND l.status='published' ORDER BY i.position,i.created_at DESC");$s->execute([':c'=>$collection['id']]);$items=$s->fetchAll();$pageTitle=$collection['title'].' | '.setting('site_name','LocalGuide');$pageDescription=text_excerpt((string)$collection['description'],150,'');include __DIR__.'/includes/header.php';?>
<main id="main" class="container lg4-page"><div class="lg4-page-heading" data-reveal="up"><span class="lg4-eyebrow">A LOCAL GUIDE COLLECTION</span><h1><?= h($collection['title']) ?></h1><p><?= h($collection['description']) ?></p><small>Curated by <?= h($collection['creator']) ?> · <?= count($items) ?> places</small></div><?php if($items): ?><div class="listing-grid lg4-listing-grid"><?php foreach($items as $listing)include __DIR__.'/includes/listing-card.php'; ?></div><?php else: ?><div class="empty-state"><h3>This collection is waiting for its first place.</h3></div><?php endif; ?></main><?php include __DIR__.'/includes/footer.php';?>
